import{_ as e,o as a,c as o,al as r}from"./chunks/framework.kcAuNBLo.js";const p=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"support/privacy-policy.md","filePath":"support/privacy-policy.md"}'),i={name:"support/privacy-policy.md"};function n(s,t,l,c,u,d){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy Policy&quot;">​</a></h1><div class="info custom-block github-alert"><p class="custom-block-title">INFO</p><p><em><strong>Last Updated:</strong> 23 Apr 2026</em></p></div><p>This Privacy Policy describes how <strong>Material Home Assistant</strong> (&quot;we&quot;, &quot;our&quot;) collects, uses, and protects your personal information when you use our service, website, and Home Assistant integrations.</p><h2 id="_1-information-collected" tabindex="-1">1. Information Collected <a class="header-anchor" href="#_1-information-collected" aria-label="Permalink to &quot;1. Information Collected&quot;">​</a></h2><p>We collect only the data strictly necessary to provide and manage the service:</p><ul><li><strong>Account Data:</strong> Email address and username provided during registration.</li><li><strong>Usage Data:</strong> Basic technical information required to verify subscription validity and ensure the correct operation of the component within your home automation ecosystem.</li><li><strong>Payment Data:</strong> Handled entirely by external providers (see Section 3).</li></ul><h2 id="_2-use-of-information" tabindex="-1">2. Use of Information <a class="header-anchor" href="#_2-use-of-information" aria-label="Permalink to &quot;2. Use of Information&quot;">​</a></h2><p>Your data is used exclusively to:</p><ul><li>Provide, manage, and maintain the component&#39;s features.</li><li>Manage the activation of &quot;Premium&quot; or &quot;Pro&quot; plans.</li><li>Send service communications, technical updates, or notifications related to your account.</li><li>Comply with legal and tax obligations.</li></ul><h2 id="_3-payment-security-and-stripe" tabindex="-1">3. Payment Security and Stripe <a class="header-anchor" href="#_3-payment-security-and-stripe" aria-label="Permalink to &quot;3. Payment Security and Stripe&quot;">​</a></h2><p>We rely on <strong>Stripe, Inc.</strong> for financial transaction management.</p><ul><li><strong>Sensitive Data Protection:</strong> Material Home Assistant <strong>does not collect, see, or store</strong> your credit card numbers, CVC codes, or expiration dates.</li><li><strong>PCI Compliance:</strong> All payment operations occur on Stripe&#39;s secure servers, ensuring the highest industry security standards (PCI-DSS).</li><li>For more details, please consult <a href="https://stripe.com/privacy" target="_blank" rel="noreferrer">Stripe&#39;s Privacy Policy</a>.</li></ul><h2 id="_4-data-retention-and-protection" tabindex="-1">4. Data Retention and Protection <a class="header-anchor" href="#_4-data-retention-and-protection" aria-label="Permalink to &quot;4. Data Retention and Protection&quot;">​</a></h2><ul><li><strong>Retention:</strong> Data is kept only for as long as necessary to provide the service or to comply with contractual and legal obligations.</li><li><strong>Security:</strong> We adopt technical and organizational measures to protect your data from unauthorized access or accidental loss. However, no transmission over the internet can be guaranteed 100% secure.</li></ul><h2 id="_5-third-party-data-sharing" tabindex="-1">5. Third-Party Data Sharing <a class="header-anchor" href="#_5-third-party-data-sharing" aria-label="Permalink to &quot;5. Third-Party Data Sharing&quot;">​</a></h2><p>We do not sell or trade your personal information for commercial purposes. Aside from Stripe (for payments), data may only be shared:</p><ul><li>If requested by judicial authorities in accordance with the law.</li><li>To protect our legal rights in the event of a breach of the Terms of Service.</li></ul><h2 id="_6-your-rights-gdpr" tabindex="-1">6. Your Rights (GDPR) <a class="header-anchor" href="#_6-your-rights-gdpr" aria-label="Permalink to &quot;6. Your Rights (GDPR)&quot;">​</a></h2><p>In accordance with the General Data Protection Regulation (GDPR), if you reside in the European Union, you have the right to:</p><ul><li>Access your personal data.</li><li>Request rectification or erasure of your data.</li><li>Object to or request the restriction of processing.</li><li>Request data portability.</li></ul><p>To exercise these rights, you may contact us at the email address provided below.</p><h2 id="_7-changes-to-the-privacy-policy" tabindex="-1">7. Changes to the Privacy Policy <a class="header-anchor" href="#_7-changes-to-the-privacy-policy" aria-label="Permalink to &quot;7. Changes to the Privacy Policy&quot;">​</a></h2><p>We reserve the right to update this policy at any time. Substantial changes will be communicated to users via the service or email. Continued use of the service after changes are published constitutes acceptance of the new policy.</p><h2 id="_8-contacts" tabindex="-1">8. Contacts <a class="header-anchor" href="#_8-contacts" aria-label="Permalink to &quot;8. Contacts&quot;">​</a></h2><p>For questions regarding your privacy or data processing, contact us at:</p><div class="info custom-block github-alert"><p class="custom-block-title">INFO</p><p></p><ul><li><strong>Email:</strong> <a href="mailto:support@materialhomeassistant.com" target="_blank" rel="noreferrer">support@materialhomeassistant.com</a></li><li><strong>Website:</strong> <a href="https://www.materialhomeassistant.com" target="_blank" rel="noreferrer">https://www.materialhomeassistant.com</a></li></ul></div>',26)])])}const m=e(i,[["render",n]]);export{p as __pageData,m as default};
